-- Persisted AI session memory for cross-session continuity.
-- Stores rolling summaries, recent turns, and user-level facts
-- so the agent can resume context after disconnect/reconnect.

CREATE TABLE IF NOT EXISTS session_memories (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    session_id    TEXT NOT NULL DEFAULT '',

    -- Rolling conversation summary (generated by LLM periodically)
    summary       TEXT NOT NULL DEFAULT '',

    -- Last N turns as JSON array: [{"role":"user","text":"..."}, ...]
    recent_turns  JSONB NOT NULL DEFAULT '[]'::jsonb,

    -- Extracted user facts/preferences (persisted across sessions)
    user_facts    JSONB NOT NULL DEFAULT '[]'::jsonb,

    -- Last user intent detected
    last_intent   TEXT NOT NULL DEFAULT '',

    -- Unresolved tasks from previous session
    pending_tasks JSONB NOT NULL DEFAULT '[]'::jsonb,

    -- Conversation mode when session ended
    last_mode     TEXT NOT NULL DEFAULT 'normal',

    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),

    -- One active memory row per user (latest session)
    UNIQUE(user_id, session_id)
);

-- Index for fast lookup by user (most recent memory)
CREATE INDEX IF NOT EXISTS idx_session_memories_user_updated
    ON session_memories (user_id, updated_at DESC);

-- Auto-update updated_at on row change
CREATE OR REPLACE FUNCTION update_session_memories_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_session_memories_updated_at
    BEFORE UPDATE ON session_memories
    FOR EACH ROW
    EXECUTE FUNCTION update_session_memories_updated_at();
